<div class="grid gap-5 md:grid-cols-2"><x-ui.input name="name" label="Nom du programme" :value="$item->name" required/><x-ui.input name="organization_name" label="Organisation" :value="$item->organization_name" required/><x-ui.select name="type" label="Type" :value="$item->type" :options="['repair'=>'Réparation','donation'=>'Don','take_back'=>'Reprise marque','recycling'=>'Recyclage','reuse'=>'Réemploi']" required/><x-ui.input name="reward_points" label="Points accordés" type="number" :value="$item->reward_points ?: 0" min="0" required/><x-ui.input name="starts_at" label="Début" type="date" :value="optional($item->starts_at)->format('Y-m-d')"/><x-ui.input name="ends_at" label="Fin" type="date" :value="optional($item->ends_at)->format('Y-m-d')"/><div class="md:col-span-2"><x-ui.textarea name="accepted_materials" label="Matières acceptées" :value="$item->accepted_materials"/></div><div class="md:col-span-2"><x-ui.textarea name="description" label="Description" :value="$item->description"/></div><div class="md:col-span-2"><x-ui.checkbox name="is_active" label="Programme actif" :checked="$item->exists ? $item->is_active : true"/></div></div>
